const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = s => String(s).toLowerCase().trim().replace(/[’‘]/g,"'").replace(/[.!?]+$/,'').replace(/\s+/g,' ');
const shuffle = a => {const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',cards:'<rect x="6" y="4" width="13" height="17" rx="2"/><path d="m3 17-1-13 13-2M10 9h5m-5 4h5"/>',game:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',edit:'<path d="m4 16 11-11 4 4L8 20H4Z M13 7l4 4M14 20h7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',write:'<path d="M11 4H4v17h16v-9M9 15l1-5L18 2l4 4-8 8Z"/>',trophy:'<path d="M7 3h10v5a5 5 0 0 1-10 0Zm0 2H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4M12 13v5m-5 3h10M9 18h6v3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5ZM20 2v4m-2-2h4"/>',book:'<path d="M12 5C9 2 5 3 2 4v15c3-1 7-2 10 1 3-3 7-2 10-1V4c-3-1-7-2-10 1Zm0 0v15"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',chevron:'<path d="m9 5 7 7-7 7"/>',flip:'<path d="M3 10a9 9 0 0 1 15-6l3 3m0-5v5h-5M21 14A9 9 0 0 1 6 20l-3-3m0 5v-5h5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5Z"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',volume:'<path d="m10 5-5 4H2v6h3l5 4ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>'};
const icon = (name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const defaults={learned:[],answers:0,correct:0,memory:[],tests:{},lastRoute:'home'};
let progress;try{progress={...defaults,...JSON.parse(localStorage.getItem('speakup-past-v1')||'{}')};if(!Array.isArray(progress.learned)||!Array.isArray(progress.memory))throw Error()}catch{progress={...defaults}}
let storageWorking=true;
function save(){try{localStorage.setItem('speakup-past-v1',JSON.stringify(progress))}catch{storageWorking=false;toast('O navegador não permitiu salvar o progresso. A prática continua disponível.')}}
function record(correct){progress.answers++;if(correct)progress.correct++;save()}
let route='home',mobileOpen=false,flash={index:0,flipped:false,filter:'all',query:''},memoryLevel=0,game=null,gapType='mixed',gapLevel='all',gap=null,timeMode='study',timeQuiz=null,testLevel=1,test=null,writingText='',writingResult=null;
const routes={home:['Início','home'],flash:['Flashcards','cards'],memory:['Memory game','game'],gaps:['Fill in the gaps','edit'],time:['Time expressions','clock'],writing:['Sentence lab','write'],test:['Teste final','trophy']};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3100)}
function go(r){route=r;mobileOpen=false;render();window.scrollTo({top:0,behavior:'instant'})}
function btn(label,action,kind='',ic=''){return `<button class="btn ${kind}" data-action="${action}">${esc(label)}${ic?icon(ic):''}</button>`}
function heading(k,title,sub,tag=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${tag?`<span class="pill">${icon('book')}${tag}</span>`:''}</div>`}
function levelCards(kind,current){const names=kind==='memory'?MEMORY_SETS.map(x=>x.name):['Essencial','Em construção','Ganhando fluência','Sem atalhos','Domínio do passado'];const desc=kind==='memory'?MEMORY_SETS.map(x=>x.desc):['Afirmativas simples','Ortografia e contexto','Past × participle','Negativas e perguntas','Contrastes e precisão'];return `<div class="level-grid">${names.map((x,i)=>`<button class="level-card ${current===i?'selected':''}" data-action="${kind}-level" data-value="${i}" aria-pressed="${current===i}"><span class="number">${i+1}</span><strong>${x}</strong><p>${desc[i]}</p></button>`).join('')}</div>`}
function render(){
$('#app').innerHTML=`<div class="shell"><aside class="sidebar ${mobileOpen?'open':''}" aria-label="Menu principal"><img class="logo" src="assets/speak-up.png" alt="Speak Up English School"><div class="side-label">SEU ESPAÇO DE PRÁTICA</div><nav class="nav">${Object.entries(routes).filter(([k])=>k!=='test').map(([k,v])=>`<button data-route="${k}" class="${route===k?'active':''}" ${route===k?'aria-current="page"':''}>${icon(v[1])}<span>${v[0]}</span></button>`).join('')}</nav><div class="side-label" style="margin-top:30px">HORA DO DESAFIO</div><nav class="nav"><button data-route="test" class="${route==='test'?'active':''}">${icon('trophy')}Teste final <span class="badge">5 NÍVEIS</span></button></nav><div class="sidebar-bottom"><div class="tip-side"><strong>${icon('spark')} Um pouco, todos os dias.</strong><p>Pequenas práticas. Grandes descobertas. O seu próximo passo começa aqui.</p></div><div class="brand-foot"><span class="avatar">S</span><span>Speak Up English School<br><span style="font-size:9px;color:#a4abb7">Learn it. Use it. Speak up.</span></span></div></div></aside><main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><img class="mobile-logo" src="assets/speak-up.png" alt="Speak Up"><div class="breadcrumb">Learning studio <span>/</span><strong>${routes[route][0]}</strong></div></div><div class="top-right"><span class="local-tag"><i></i>${storageWorking?'Progresso neste navegador':'Sessão sem salvamento'}</span><span class="avatar-main" aria-label="Aluno Speak Up">SU</span></div></header><div class="content" id="content">${({home:homeView,flash:flashView,memory:memoryView,gaps:gapsView,time:timeView,writing:writingView,test:testView})[route]()}</div></main></div>`;
}
function homeView(){const pct=progress.answers?Math.round(progress.correct/progress.answers*100):0;return `${heading('PAST STUDIO','Seu próximo passo começa aqui.','Um espaço para praticar, errar, descobrir e aprender no seu ritmo.','Simple Past')}
<section class="hero"><div class="hero-copy"><span class="hero-kicker">A LITTLE PRACTICE. A LOT OF PROGRESS.</span><h2>O passado fica mais fácil<br>com um pouco de <span>prática.</span></h2><p>Explore verbos, conecte ideias e ganhe confiança para contar as suas histórias em inglês.</p>${btn('Vamos praticar','start-flash','','arrow')}</div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-card"><small>BASE FORM</small><h3>go</h3><p>ir</p><div class="card-line"></div></div><div class="art-card back"><small>SIMPLE PAST</small><h3>went</h3><p>Ontem já é outra história.</p><div class="card-line"></div></div><span class="spark">✦</span><div class="art-label">✓ &nbsp; One step closer!</div></div></section>
<div class="stats"><div class="stat"><span class="stat-icon">${icon('cards')}</span><div><strong>${progress.learned.length} <span class="mini">/ 104</span></strong><p>verbos marcados como aprendidos</p></div></div><div class="stat"><span class="stat-icon t-green">${icon('target')}</span><div><strong>${pct}<span class="mini">%</span></strong><p>acertos em ${progress.answers} respostas</p></div></div><div class="stat"><span class="stat-icon t-yellow">${icon('trophy')}</span><div><strong>${Object.values(progress.tests).filter(x=>x>=70).length} <span class="mini">/ 5</span></strong><p>níveis com 70% ou mais</p></div></div></div>
<div class="section-head"><h2>Como você quer praticar hoje?</h2><span>6 jeitos de dar o próximo passo</span></div><div class="modules">
${moduleTile('flash','cards','','MEMORIZE','Flashcards','Vire o card. Descubra o passado. Leve os verbos com você.','104 verbos irregulares')}
${moduleTile('memory','game','t-purple','CONECTE','Memory game','Encontre os pares e treine sua memória jogando.','5 sets · dificuldade crescente')}
${moduleTile('gaps','edit','t-red','COMPLETE','Fill in the gaps','O verbo certo, na hora certa. Complete as frases no passado.','Regulares, irregulares e mixed')}
${moduleTile('time','clock','t-green','EXPLORE','Time expressions','Yesterday, last week, two days ago… Cada história tem seu tempo.','Expressões + prática')}
${moduleTile('writing','write','t-yellow','CRIE','Sentence lab','Suas ideias em inglês. Escreva e revise a estrutura do passado.','Escrita com feedback')}
${moduleTile('test','trophy','','DESAFIE-SE','Pronto para o próximo nível?','Junte o que aprendeu e descubra até onde você chegou.','Teste final · 5 níveis','test-tile')}</div>
<p class="bottom-note">${icon('heart')} Feito para o seu ritmo. Seu progresso fica salvo neste navegador.</p>`}
function moduleTile(r,ic,color,type,title,desc,foot,extra=''){return `<button class="module ${extra}" data-route="${r}"><span class="module-top"><span class="module-icon ${color}">${icon(ic)}</span><span class="module-type">${type}</span></span><h3>${title}</h3><p>${desc}</p><span class="module-foot">${foot}${icon('arrow')}</span></button>`}
function flashDeck(){let d=VERBS.filter(v=>flash.filter==='all'||(flash.filter==='learned'?progress.learned.includes(v.base):!progress.learned.includes(v.base)));if(flash.query)d=d.filter(v=>norm(v.base+' '+v.past+' '+v.pt).includes(norm(flash.query)));return d}
function flashView(){const d=flashDeck();flash.index=Math.min(flash.index,Math.max(0,d.length-1));const v=d[flash.index];return `${heading('01 / MEMORIZE','Verbo por verbo. Card por card.','Só verbos irregulares. Clique no card para descobrir as formas no passado.','104 verbos do seu material')}<div class="toolbar"><div class="tabs">${[['all','Todos'],['review','Para revisar'],['learned','Aprendidos']].map(([k,l])=>`<button data-action="flash-filter" data-value="${k}" class="${flash.filter===k?'selected':''}">${l}</button>`).join('')}</div><input class="search" id="verb-search" aria-label="Buscar verbo ou tradução" placeholder="Buscar verbo ou tradução…" value="${esc(flash.query)}"></div>${!v?'<div class="panel empty">Nenhum verbo neste filtro.<br>Experimente outro filtro ou busca.</div>':`<div class="practice-shell"><div class="practice-meta"><span>Card ${flash.index+1} de ${d.length}</span><span>${progress.learned.includes(v.base)?'✓ Marcado como aprendido':'Seu ritmo, sua descoberta'}</span></div><div class="progressbar"><div style="width:${(flash.index+1)/d.length*100}%"></div></div><button class="flashcard" data-action="flip" aria-label="${flash.flipped?'Formas de '+esc(v.base)+'. Clique para voltar.':'Verbo '+esc(v.base)+'. Clique para revelar.'}" style="margin-top:18px"><small>${flash.flipped?'AS TRÊS FORMAS':'BASE FORM'}</small><span class="word">${esc(v.base)}</span><span class="translation">${esc(v.pt)}</span>${flash.flipped?`<span class="forms"><span><small>BASE</small><b>${esc(v.base)}</b></span><span><small>SIMPLE PAST</small><b>${esc(v.past)}</b></span><span><small>PAST PARTICIPLE</small><b>${esc(v.part)}</b></span></span>`:''}<span class="flip-hint">${icon('flip')} ${flash.flipped?'Clique para voltar':'Clique para virar o card'}</span></button><div class="card-actions">${btn('Anterior','flash-prev','light')}${btn(progress.learned.includes(v.base)?'Revisar depois':'Já aprendi','flash-learn',progress.learned.includes(v.base)?'light':'','check')}${btn('Próximo','flash-next','light','arrow')}</div><p class="help-note"><strong>Uma diferença importante:</strong> no Simple Past afirmativo, use a segunda coluna. A terceira é o particípio, usado em outras estruturas, como “I have gone”. <br>“Read” se escreve igual nas três formas, mas a pronúncia no passado e no particípio é /red/.</p></div>`}`}
function newGame(){const verbs=MEMORY_SETS[memoryLevel].pairs.map(b=>VERBS.find(v=>v.base===b));game={id:Math.random(),cards:shuffle(verbs.flatMap(v=>[{id:v.base,form:'base',word:v.base},{id:v.base,form:'past',word:v.past}])),open:[],matched:[],moves:0,locked:false,done:false,started:false}}
function memoryView(){if(!game)newGame();const found=game.matched.length;return `${heading('02 / CONECTE','Encontre o par. Fixe o passado.','Combine a forma base com o Simple Past do mesmo verbo. Cada set tem verbos diferentes.')} ${levelCards('memory',memoryLevel)}<div class="panel practice-shell"><div class="memory-info"><div><h3 style="font-size:16px">Set ${memoryLevel+1} · ${MEMORY_SETS[memoryLevel].name}</h3><p class="sub">${found} de ${MEMORY_SETS[memoryLevel].pairs.length} pares · ${game.moves} ${game.moves===1?'tentativa':'tentativas'}</p></div>${btn('Recomeçar','memory-reset','light','reset')}</div><div class="game-board">${game.cards.map((c,i)=>{const matched=game.matched.includes(c.id),show=matched||game.open.includes(i);return `<button data-action="memory-card" data-value="${i}" class="memory-card ${matched?'matched':show?'':'hidden-card'}" ${matched||game.locked||game.open.includes(i)?'disabled':''} aria-label="${show?esc(c.word)+' '+c.form:'Revelar carta '+(i+1)}">${show?`<small>${c.form==='base'?'BASE FORM':'SIMPLE PAST'}</small>${esc(c.word)}${matched?'<small>✓</small>':''}`:icon('cards')}</button>`}).join('')}</div>${game.done?`<div class="finished-banner" role="status"><h3>Todos os pares encontrados!</h3><p>Você completou o set em ${game.moves} ${game.moves===1?'tentativa':'tentativas'}. Boa conexão!</p>${memoryLevel<4?btn('Ir para o próximo set','memory-next','','arrow'):btn('Explorar o teste final','open-test','','trophy')}</div>`:''}<p class="help-note">Observe também a etiqueta: um par sempre tem uma <strong>BASE FORM</strong> e um <strong>SIMPLE PAST</strong>. Isso ajuda a distinguir “lie → lay” de “lay → laid”.</p></div>`}
function openMemory(i){if(game.locked||game.matched.includes(game.cards[i].id)||game.open.includes(i))return;game.open.push(i);game.started=true;if(game.open.length===2){game.moves++;const [a,b]=game.open.map(x=>game.cards[x]);if(a.id===b.id&&a.form!==b.form){game.matched.push(a.id);game.open=[];if(game.matched.length===MEMORY_SETS[memoryLevel].pairs.length){game.done=true;if(!progress.memory.includes(memoryLevel)){progress.memory.push(memoryLevel);save()}}}else{game.locked=true;const current=game.id;setTimeout(()=>{if(game&&game.id===current){game.open=[];game.locked=false;if(route==='memory')render()}},1100)}}render()}
function newGap(){const pool=EXERCISES.filter(x=>(gapType==='mixed'||x.type===gapType)&&(gapLevel==='all'||x.level===Number(gapLevel)));gap={questions:shuffle(pool),index:0,results:[],value:'',submitted:false}}
function gapsView(){if(!gap)newGap();return `${heading('03 / COMPLETE','Uma frase. O verbo certo.','Pratique o Simple Past com afirmativas, negativas e perguntas.')}<div class="toolbar"><div class="tabs">${[['regular','Regulares'],['irregular','Irregulares'],['mixed','Mixed']].map(([k,l])=>`<button data-action="gap-type" data-value="${k}" class="${gapType===k?'selected':''}">${l}</button>`).join('')}</div><select id="gap-level" aria-label="Dificuldade dos exercícios"><option value="all">Todas as dificuldades</option>${[1,2,3,4,5].map(i=>`<option value="${i}" ${gapLevel===String(i)?'selected':''}>Nível ${i}</option>`).join('')}</select></div>${practiceView(gap,'gap')}`}
function practiceView(session,kind){if(session.index>=session.questions.length){const right=session.results.filter(x=>x.correct).length;return `<div class="panel practice-shell"><div class="results"><span class="eyebrow">PRÁTICA CONCLUÍDA</span><div class="score-ring"><b>${Math.round(right/session.questions.length*100)}%</b><span>${right} de ${session.questions.length} acertos</span></div><h2>Cada tentativa conta.</h2><p>Revise as explicações e tente de novo quando quiser.</p><div class="card-actions">${btn('Praticar novamente',kind+'-restart','','reset')}${session.results.some(x=>!x.correct)?btn('Revisar só os erros',kind+'-mistakes','light'):''}</div></div>${session.results.filter(x=>!x.correct).map(reviewItem).join('')}</div>`}const q=session.questions[session.index];const last=session.results.at(-1);return `<div class="practice-shell"><div class="practice-meta"><span>Questão ${session.index+1} de ${session.questions.length}</span><span>${q.level?'Nível '+q.level:'Expressões de tempo'}</span></div><div class="progressbar"><div style="width:${session.index/session.questions.length*100}%"></div></div><div class="panel" style="margin-top:18px"><span class="eyebrow">${kind==='gap'?'COMPLETE COM O SIMPLE PAST':'COMPLETE A EXPRESSÃO'}</span><p class="question">${esc(q.q).replace('___','<span style="color:var(--red)">______</span>')}</p>${q.hint?`<p class="section-caption">Verbo na forma base: <strong>${esc(q.hint)}</strong></p>`:''}<form id="${kind}-form"><div class="answer-row"><input autocomplete="off" autocapitalize="none" spellcheck="false" class="answer-input" id="practice-answer" placeholder="Digite sua resposta…" aria-label="Sua resposta" value="${esc(session.value)}" ${session.submitted?'disabled':''} required>${!session.submitted?'<button class="btn" type="submit">Verificar resposta</button>':''}</div></form>${session.submitted?`<div class="feedback ${last.correct?'good':'bad'}" role="status"><h3>${last.correct?'Isso mesmo!':'Vamos ajustar?'}</h3>${!last.correct?`Resposta esperada: <strong>${esc(q.answers.join(' / '))}</strong>.<br>`:''}${esc(q.explain)}<br>${btn(session.index===session.questions.length-1?'Ver resultado':'Próxima questão',kind+'-next','','arrow')}</div>`:''}</div><div class="quiz-bottom"><span class="storage-note">${session.results.filter(x=>x.correct).length} ${session.results.filter(x=>x.correct).length===1?'acerto':'acertos'} nesta rodada</span><button class="text-button" data-action="${kind}-restart">Reiniciar rodada</button></div></div>`}
function submitPractice(kind){const s=kind==='gap'?gap:timeQuiz;if(s.submitted)return;const value=$('#practice-answer').value.trim();if(!value)return;const q=s.questions[s.index];const correct=q.answers.some(x=>norm(x)===norm(value));s.value=value;s.results.push({q,value,correct});s.submitted=true;record(correct);render()}
function reviewItem(r){return `<div class="review-item"><h3>${esc(r.q.q)}</h3><p class="${r.correct?'correct':'incorrect'}">${r.correct?'✓':'×'} Sua resposta: ${esc(r.value||'(em branco)')}</p>${!r.correct?`<p class="correct">Resposta: ${esc(r.q.answers.join(' / '))}</p>`:''}<p>${esc(r.q.explain)}</p></div>`}
function timeView(){return `${heading('04 / EXPLORE','Toda história tem seu tempo.','Aprenda a dizer quando aconteceu. Depois, coloque as expressões em prática.')}<div class="toolbar"><div class="tabs"><button data-action="time-mode" data-value="study" class="${timeMode==='study'?'selected':''}">Estudar expressões</button><button data-action="time-mode" data-value="practice" class="${timeMode==='practice'?'selected':''}">Praticar</button></div></div>${timeMode==='study'?`<div class="expression-grid">${EXPRESSIONS.map(x=>`<article class="expression" style="background:#fff"><span class="tag">${esc(x.category)}</span><h3>${esc(x.word)}</h3><p style="color:var(--red)">${esc(x.pt)}</p><p>${esc(x.rule)}</p><p class="example">“${esc(x.example)}”</p></article>`).join('')}</div><p class="help-note"><strong>Dica:</strong> yesterday, last e ago normalmente não levam preposição antes. Compare: <strong>in 2020</strong>, mas <strong>last year</strong>. Uma expressão como “on Monday” pode se referir ao passado ou ao futuro; o contexto e o verbo esclarecem o sentido.</p>`:(timeQuiz||(timeQuiz={questions:shuffle(TIME_QUIZ),index:0,results:[],value:'',submitted:false}),practiceView(timeQuiz,'time'))}`}
function writingView(){return `${heading('05 / CRIE','Sua história começa com uma frase.','Escreva uma frase em inglês e confira a estrutura do Simple Past.')}<div class="writing-layout"><section class="panel"><label class="form-label" for="sentence">O que aconteceu?</label><p class="sub">Tente usar yesterday, last week ou uma outra expressão de passado.</p><form id="writing-form"><textarea id="sentence" maxlength="500" placeholder="Ex.: I went to the park yesterday." required>${esc(writingText)}</textarea><div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><span class="storage-note">Uma frase por vez · até 500 caracteres</span><button class="btn" type="submit">Revisar frase ${icon('arrow')}</button></div></form><p class="help-note"><strong>Como funciona:</strong> revisão por regras, focada em Simple Past. Verifica formas verbais, did/didn’t, was/were e algumas expressões de tempo. Pode não identificar todos os erros de vocabulário, sentido ou gramática. Se a estrutura não for reconhecida, o resultado será inconclusivo.</p>${writingResult?writingFeedback(writingResult):''}</section><aside class="panel side-tips"><h3>Uma ajudinha para começar</h3><p>Clique em um exemplo para experimentar.</p>${['I went to the park yesterday.',"She didn't went to school yesterday.",'Did you watched the film last night?','They was tired last week.'].map(s=>`<button class="example-btn" data-action="writing-example" data-value="${esc(s)}">${esc(s)} ${icon('arrow')}</button>`).join('')}<div class="inline-sep"></div><h3>Guarde estas três estruturas</h3><p><strong>Afirmativa</strong><br><code>I watched a film.</code><br><br><strong>Negativa</strong><br><code>I didn’t watch a film.</code><br><br><strong>Pergunta</strong><br><code>Did you watch a film?</code></p></aside></div>`}
function writingFeedback(r){return `<div class="feedback ${r.status==='good'?'good':r.status==='bad'?'bad':'warning'}" role="status"><h3>${r.status==='good'?'Estrutura de Simple Past reconhecida':r.status==='bad'?'Tem um ajuste para fazer':'Ainda não consigo avaliar com segurança'}</h3>${r.messages.map(s=>`<p>${esc(s)}</p>`).join('')}${r.correction?`<p style="margin-top:9px"><strong>Sugestão:</strong> ${esc(r.correction)}</p>`:''}${r.status==='good'?'<p style="margin-top:8px">Não encontrei problemas nas regras verificadas. Isso não garante uma revisão completa de todos os aspectos da frase.</p>':''}</div>`}
function analyzeSentence(text){
const original=text.trim(),s=norm(original),msgs=[];let corrected=original;let recognized=false;const tokens=s.match(/[a-z]+(?:'[a-z]+)?/g)||[];
if(tokens.length<3)return {status:'unknown',messages:['Escreva uma frase completa com sujeito e verbo. Ex.: I worked yesterday.']};
if(/[\n]/.test(original)||/[.!?]\s+\S/.test(original))return {status:'unknown',messages:['Vamos revisar uma frase por vez. Separe as suas frases e tente novamente.']};
const all=Object.fromEntries([...VERBS.map(v=>[v.base,v.past]),...Object.entries(REGULARS)]),subject='(?:i|you|he|she|it|we|they)',knownPast=Object.values(all).flatMap(v=>v.split('/')).filter(v=>!v.includes(' '));
const replaceWord=(bad,good)=>{corrected=corrected.replace(new RegExp('\\b'+bad+'\\b','i'),good)};
const canonicalBase=word=>Object.entries(all).filter(([base,past])=>past.split('/').includes(word)||VERBS.find(v=>v.base===base)?.part.split('/').includes(word)).map(([base])=>base);
// After did, reject past/participle and inflected verb forms; known base forms are allowed.
let aux=s.match(new RegExp("\\b(didn't|did not|did)\\s+(?:"+subject+"\\s+)?([a-z]+)\\b"));
if(aux){const word=aux[2];if(all[word]){recognized=true;if(word==='be'){msgs.push('Com be, use was/were diretamente. Ex.: “Was she tired?” ou “She wasn’t tired.”');recognized=false}}
else{const bases=canonicalBase(word);const third=word.endsWith('ies')?word.slice(0,-3)+'y':word.endsWith('es')&&all[word.slice(0,-2)]?word.slice(0,-2):word.endsWith('s')?word.slice(0,-1):null;const base=bases[0]||(third&&all[third]?third:null);if(base){msgs.push(`Depois de did/didn’t, use o verbo na forma base: ${base}. O auxiliar did já marca o passado.`);replaceWord(word,base)}else if(word==='was'||word==='were'){msgs.push('Não combine did com was/were. Use “Was she…?” / “Were they…?” ou “She wasn’t…” / “They weren’t…”.')} }
if(!new RegExp('^(?:(?:why|when|where|what|how|who)\\s+)?did\\s+'+subject+'\\s+').test(s)&&!new RegExp('^'+subject+"\\s+(?:didn't|did not)\\s+").test(s)&&!new RegExp('^'+subject+'\\s+did\\s+').test(s)){recognized=false}
}
const agreement=s.match(/\b(i|he|she|it|we|you|they)\s+(was|were|wasn't|weren't)\b/);
if(agreement){recognized=true;const singular=['i','he','she','it'].includes(agreement[1]);const wrong=singular?['were',"weren't"].includes(agreement[2]):['was',"wasn't"].includes(agreement[2]);if(wrong){const right=singular?(agreement[2].includes("n't")?"wasn't":'was'):(agreement[2].includes("n't")?"weren't":'were');msgs.push(`Com ${agreement[1]}, use ${right}. I/he/she/it combinam com was; you/we/they, com were.`);replaceWord(agreement[2],right)}const after=s.slice(agreement.index+agreement[0].length).trim().split(' ')[0];if(all[after]&&after!=='be'&&!knownPast.includes(after)){msgs.push('No Simple Past afirmativo, não coloque was/were antes da forma base. Use o verbo no passado: “I went”, por exemplo.');recognized=false}if(knownPast.includes(after)&&!['hurt','lost','gone','broken','tired','known','cut','shut','born','read'].includes(after)){msgs.push('Essa combinação de was/were com verbo no passado precisa de revisão. Para Simple Past ativo, use “She went”, por exemplo. “She was going” pertence ao Past Continuous.');recognized=false}}
const beQuestion=s.match(/^(was|were|wasn't|weren't)\s+(i|he|she|it|we|you|they)\b/);if(beQuestion){recognized=true;const singular=['i','he','she','it'].includes(beQuestion[2]);if(singular===beQuestion[1].startsWith('were')){const right=singular?'was':'were';msgs.push(`Na pergunta com ${beQuestion[2]}, use ${right}.`);replaceWord(beQuestion[1],right)}}
const statement=s.match(/^(i|you|he|she|it|we|they)\s+([a-z]+)\b/);if(statement&&!aux&&!agreement){const word=statement[2];if(knownPast.includes(word))recognized=true;else if(all[word]){const past=all[word].split('/')[0];if(past!==word){msgs.push(`Para contar uma ação concluída no passado, use ${past}, passado de ${word}.`);corrected=corrected.replace(new RegExp('^(I|you|he|she|it|we|they)\\s+'+word+'\\b','i'),(_,sub)=>sub+' '+past)}}else{let found=false;for(const [base,past]of Object.entries(all)){const bad=[base+'ed',base+'d',base.endsWith('y')?base.slice(0,-1)+'ied':''];if(bad.includes(word)&&!past.split('/').includes(word)){msgs.push(`A forma de passado de ${base} é ${past.replaceAll('/',' / ')}, não ${word}.`);replaceWord(word,past.split('/')[0]);found=true;break}}
if(!found){const p=VERBS.find(v=>v.part.split('/').includes(word)&&!v.past.split('/').includes(word));if(p){msgs.push(`${word} é o particípio. No Simple Past afirmativo, use ${p.past}.`);replaceWord(word,p.past.split('/')[0])}}}}
const presentBe=s.match(/^(i|you|he|she|it|we|they)\s+(am|is|are)\b/);if(presentBe){const right=['i','he','she','it'].includes(presentBe[1])?'was':'were';msgs.push(`Para praticar o passado de be com ${presentBe[1]}, use ${right}.`);replaceWord(presentBe[2],right);recognized=false}
if(statement&&!aux&&!agreement&&!presentBe){const w=statement[2];const base=w==='goes'?'go':w==='does'?'do':w==='has'?'have':w.endsWith('ies')?w.slice(0,-3)+'y':w.endsWith('es')&&all[w.slice(0,-2)]?w.slice(0,-2):w.endsWith('s')?w.slice(0,-1):null;if(base&&all[base]&&!knownPast.includes(w)){const past=all[base].split('/')[0];msgs.push(`${w} é uma forma do presente. No Simple Past afirmativo, use ${past}.`);replaceWord(w,past)}}
if(/\byesterday night\b/.test(s)){msgs.push('Para “ontem à noite”, use last night.');corrected=corrected.replace(/yesterday night/i,'last night')}
if(/\b(in|on|at)\s+(yesterday|last\s+(?:night|week|month|year|weekend))\b/.test(s)){msgs.push('Yesterday e last + período não precisam de in, on ou at antes.');corrected=corrected.replace(/\b(in|on|at)\s+(yesterday|last\s+(?:night|week|month|year|weekend))/i,'$2')}
if(/\bago\s+(?:\d+|one|two|three|four|five|an?)\s+(?:days?|weeks?|months?|years?|hours?)\b/.test(s)){msgs.push('Ago vem depois da duração: two days ago, an hour ago.');corrected=corrected.replace(/\bago\s+((?:\d+|one|two|three|four|five|an?)\s+(?:days?|weeks?|months?|years?|hours?))/i,'$1 ago')}
if(/\b(?:tomorrow|next week|next month|next year)\b/.test(s)){msgs.push('Essa expressão aponta para o futuro. Para praticar Simple Past, experimente yesterday, last week ou last year.');recognized=false}
if(/\b(?:have|has)\s+(?:been|gone|done|seen|written|eaten|taken)\b/.test(s))return {status:'unknown',messages:['Essa estrutura é Present Perfect. Este laboratório revisa Simple Past. Compare: “I have seen it” e “I saw it yesterday”.']};
if(msgs.length)return {status:'bad',messages:msgs,correction:corrected!==original?corrected:null};
// Be conservative with patterns outside the supported one-clause constructions.
if(tokens.includes('and')||tokens.includes('but')||tokens.includes('because')||tokens.some(t=>t.endsWith('ing'))&&!/\b(?:morning|evening)\b/.test(s))recognized=false;
if(/\b(?:did|didn't|was|were|went|ate|saw|bought|made|took|gave|met|wrote|spoke|drank|played|worked|watched)\s*$/.test(s)&&tokens.length<4)recognized=false;
if(!recognized)return {status:'unknown',messages:['Não reconheci uma estrutura que eu consiga validar com segurança. Isso não significa que a frase esteja errada.','Experimente uma frase simples: sujeito + verbo no passado + complemento. Ex.: “They visited London last year.” Para estruturas mais livres, confirme com seu professor.']};
return {status:'good',messages:[aux?'O auxiliar did está acompanhado de verbo na forma base.':agreement||beQuestion?'O uso de was/were está de acordo com o sujeito.':'A forma verbal usada está na lista de formas do Simple Past.']};
}
function makeTest(){const pool=shuffle(EXERCISES.filter(q=>q.level===testLevel));const chosen=[...pool.filter(x=>x.type==='irregular').slice(0,4),...pool.filter(x=>x.type==='regular').slice(0,4)];const timeOptions=[0,2,1,4,9];const tq={...TIME_QUIZ[timeOptions[testLevel-1]],level:testLevel};test={level:testLevel,questions:shuffle([...chosen,tq,SPECIAL_TESTS[testLevel-1]]),index:0,responses:{},done:false};}
function testView(){return `${heading('06 / DESAFIE-SE','O que você já consegue fazer?','Cinco níveis para testar sua evolução. A correção completa aparece ao finalizar.')} ${!test||test.done?levelCards('test',testLevel-1):''}${!test?testIntro():test.done?testResults():testQuestion()}`}
function testIntro(){return `<section class="panel"><div class="test-intro"><div class="big-icon">${icon('trophy')}</div><span class="eyebrow">NÍVEL ${testLevel}</span><h2 style="margin-top:12px">Um novo desafio te espera.</h2><p>Responda 10 questões sobre verbos e expressões de tempo. Sem cronômetro: o foco é entender. Você pode voltar às perguntas antes de finalizar.</p><div class="test-tags"><span class="pill">${icon('edit')}10 questões</span><span class="pill">${icon('clock')}No seu ritmo</span><span class="pill">${icon('target')}Meta: 70% de acertos</span></div>${progress.tests[testLevel]!==undefined?`<p style="margin-bottom:20px">Seu melhor resultado neste nível: <strong>${progress.tests[testLevel]}%</strong></p>`:''}${btn('Começar o nível '+testLevel,'test-start','','arrow')}</div></section>`}
function testQuestion(){const q=test.questions[test.index],value=test.responses[q.id]||'',count=Object.keys(test.responses).filter(k=>test.responses[k]?.trim()).length;return `<div class="practice-shell"><div class="practice-meta"><span>Nível ${test.level} · Questão ${test.index+1} de ${test.questions.length}</span><span>${count} respondidas</span></div><div class="progressbar"><div style="width:${count/test.questions.length*100}%"></div></div><div class="panel" style="margin-top:18px"><span class="eyebrow">${q.options?'ESCOLHA A ALTERNATIVA CORRETA':'COMPLETE A FRASE'}</span><p class="question">${esc(q.q).replace('___','<span style="color:var(--red)">______</span>')}</p>${q.hint?`<p class="section-caption">Verbo na forma base: <strong>${esc(q.hint)}</strong></p>`:''}${q.options?`<div class="options">${q.options.map((x,i)=>`<button class="option ${value===x?'selected':''}" data-action="test-option" data-value="${i}" aria-pressed="${value===x}"><span class="letter">${String.fromCharCode(65+i)}</span>${esc(x)}</button>`).join('')}</div>`:`<input class="answer-input" style="width:100%" id="test-answer" autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="Resposta do teste" placeholder="Digite sua resposta…" value="${esc(value)}">`}<div class="quiz-bottom"><button class="btn light" data-action="test-prev" ${test.index===0?'disabled':''}>Anterior</button>${test.index<test.questions.length-1?btn('Próxima questão','test-next','','arrow'):btn('Revisar e finalizar','test-finish','red','check')}</div></div><p class="help-note">O resultado só aparece ao finalizar. Todas as questões precisam estar respondidas. Você pode sair desta área e retomar o teste durante esta sessão.</p></div>`}
function finishTest(){captureTest();const empty=test.questions.findIndex(q=>!test.responses[q.id]?.trim());if(empty>=0){test.index=empty;toast('Ainda falta responder esta questão.');render();return}test.results=test.questions.map(q=>({q,value:test.responses[q.id],correct:q.answers.some(a=>norm(a)===norm(test.responses[q.id]))}));test.score=Math.round(test.results.filter(x=>x.correct).length/test.questions.length*100);test.done=true;progress.tests[test.level]=Math.max(progress.tests[test.level]||0,test.score);progress.answers+=test.results.length;progress.correct+=test.results.filter(x=>x.correct).length;save();render();window.scrollTo(0,0)}
function testResults(){return `<div class="panel practice-shell"><div class="results"><span class="eyebrow">NÍVEL ${test.level} · RESULTADO FINAL</span><div class="score-ring" style="border-color:${test.score>=70?'#cfe8da':'#f2d9df'}"><b>${test.score}%</b><span>${test.results.filter(x=>x.correct).length} de 10 acertos</span></div><h2>${test.score>=70?'Mais um passo conquistado!':'Vamos transformar os erros em prática.'}</h2><p>${test.score>=70?'Você atingiu a meta deste nível. Continue explorando!':'A meta é 70%. Leia o feedback, pratique e tente novamente.'}</p><div class="card-actions">${btn('Tentar novamente','test-retry','light','reset')}${test.level<5?btn('Próximo nível','test-next-level','','arrow'):btn('Voltar às atividades','open-home','','arrow')}</div></div><div class="section-head"><h2>Seu teste, questão por questão</h2></div>${test.results.map(reviewItem).join('')}</div>`}
function captureTest(){if(test&&!test.done){const el=$('#test-answer');if(el)test.responses[test.questions[test.index].id]=el.value.trim()}}
$('#app').addEventListener('click',e=>{const n=e.target.closest('[data-route],[data-action]');if(!n)return;if(n.dataset.route){captureTest();go(n.dataset.route);return}const a=n.dataset.action,v=n.dataset.value;
switch(a){case'menu':mobileOpen=!mobileOpen;$('.sidebar').classList.toggle('open',mobileOpen);break;case'start-flash':go('flash');break;case'open-home':go('home');break;case'open-test':go('test');break;
case'flip':flash.flipped=!flash.flipped;render();break;case'flash-filter':flash.filter=v;flash.index=0;flash.flipped=false;render();break;case'flash-prev':flash.index=(flash.index-1+flashDeck().length)%flashDeck().length;flash.flipped=false;render();break;case'flash-next':flash.index=(flash.index+1)%flashDeck().length;flash.flipped=false;render();break;case'flash-learn':{const word=flashDeck()[flash.index].base;if(progress.learned.includes(word)){progress.learned=progress.learned.filter(x=>x!==word);toast('Este verbo voltou para a revisão.')}else{progress.learned.push(word);toast('Verbo marcado como aprendido!')}save();render();break}
case'memory-level':memoryLevel=Number(v);newGame();render();break;case'memory-reset':newGame();render();break;case'memory-next':memoryLevel++;newGame();render();break;case'memory-card':openMemory(Number(v));break;
case'gap-type':gapType=v;newGap();render();break;case'gap-restart':newGap();render();break;case'gap-next':gap.index++;gap.value='';gap.submitted=false;render();$('#practice-answer')?.focus();break;case'gap-mistakes':gap={questions:shuffle(gap.results.filter(x=>!x.correct).map(x=>x.q)),index:0,results:[],value:'',submitted:false};render();break;
case'time-mode':timeMode=v;render();break;case'time-restart':timeQuiz={questions:shuffle(TIME_QUIZ),index:0,results:[],value:'',submitted:false};render();break;case'time-next':timeQuiz.index++;timeQuiz.value='';timeQuiz.submitted=false;render();$('#practice-answer')?.focus();break;case'time-mistakes':timeQuiz={questions:shuffle(timeQuiz.results.filter(x=>!x.correct).map(x=>x.q)),index:0,results:[],value:'',submitted:false};render();break;
case'writing-example':writingText=v;writingResult=null;render();$('#sentence').focus();break;
case'test-level':testLevel=Number(v)+1;if(test?.done)test=null;render();break;case'test-start':makeTest();render();break;case'test-option':test.responses[test.questions[test.index].id]=test.questions[test.index].options[Number(v)];render();break;case'test-prev':captureTest();test.index--;render();break;case'test-next':captureTest();test.index++;render();$('#test-answer')?.focus();break;case'test-finish':finishTest();break;case'test-retry':testLevel=test.level;makeTest();render();break;case'test-next-level':testLevel=test.level+1;test=null;render();window.scrollTo(0,0);break;
}});
$('#app').addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='gap-form')submitPractice('gap');if(e.target.id==='time-form')submitPractice('time');if(e.target.id==='writing-form'){writingText=$('#sentence').value.trim();if(!writingText)return;writingResult=analyzeSentence(writingText);render()}});
$('#app').addEventListener('input',e=>{if(e.target.id==='verb-search'){const start=e.target.selectionStart;flash.query=e.target.value;flash.index=0;flash.flipped=false;render();$('#verb-search').focus();$('#verb-search').setSelectionRange(start,start)}if(e.target.id==='sentence'){writingText=e.target.value}if(e.target.id==='practice-answer'){const ss=route==='gaps'?gap:timeQuiz;if(ss)ss.value=e.target.value}if(e.target.id==='test-answer'){test.responses[test.questions[test.index].id]=e.target.value}});
$('#app').addEventListener('change',e=>{if(e.target.id==='gap-level'){gapLevel=e.target.value;newGap();render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileOpen){mobileOpen=false;$('.sidebar').classList.remove('open')}});
render();
